<form method="get" class="toolbar"><input type="hidden" name="page" value="rooms"><input type="hidden" name="type" value="<?= e($type) ?>"><div class="search-field <?= $admin?'search-compact':'' ?>"><?= icon('search') ?><input type="search" name="q" value="<?= e($search) ?>" aria-label="Buscar sala" placeholder="<?= $admin?'Buscar sala...':'Buscar por sala, tipo ou recurso...' ?>"><button type="submit" class="search-submit" aria-label="Pesquisar"><?= icon('arrow-right') ?></button></div><?php if($admin): ?><a class="button" href="<?= e(url('rooms',['action'=>'create'])) ?>"><?= icon('plus') ?>Nova sala</a><?php else: ?><button type="button" class="button button-outline" data-toggle="room-filters" aria-expanded="<?= $capacity||$available?'true':'false' ?>"><?= icon('sliders-horizontal') ?>Filtros</button><?php endif; ?><div class="filter-panel" id="room-filters" <?= !$capacity&&!$available?'hidden':'' ?>><label>Capacidade mínima<input type="number" min="0" max="2000" name="capacity" value="<?= $capacity ?>"></label><label class="checkbox"><input type="checkbox" name="available" value="1" <?= $available?'checked':'' ?>>Somente disponíveis</label><button class="button button-small">Aplicar filtros</button><a href="<?= e(url('rooms')) ?>" class="text-link">Limpar</a></div></form>
<?php if(!$admin): ?><div class="type-tabs" aria-label="Tipos de sala"><?php foreach([''=>'Todos']+options_for(\App\Models\Room::TYPES) as $key=>$label): ?><a class="chip <?= $type===$key?'selected':'' ?>" href="<?= e(url('rooms',['type'=>$key,'q'=>$search,'capacity'=>$capacity,'available'=>$available?'1':''])) ?>" <?= $type===$key?'aria-current="true"':'' ?>><?= e($label) ?></a><?php endforeach; ?></div><div class="room-grid"><?php foreach($rows as $room): $features=array_map('trim',explode(',',$room['features'])); ?><a class="room-card" href="<?= e(url('rooms',['action'=>'show','id'=>$room['id']])) ?>"><div class="room-photo"><img src="public/assets/images/<?= e($room['image']) ?>" alt="<?= e($room['name']) ?>" loading="lazy"><span class="photo-type"><?= icon(room_icon($room['type'])) ?><?= e($room['type']) ?></span><?= badge($room['status']) ?></div><div class="room-card-body"><h3><?= e($room['name']) ?></h3><p class="inline-meta"><?= icon('users') ?><?= (int)$room['capacity'] ?> pessoas <span class="meta-spacer"></span><?= icon('map-pin') ?><?= e($room['floor']) ?></p><div class="feature-list"><?php foreach(array_slice($features,0,3) as $feature): ?><span><?= icon('check') ?><?= e($feature) ?></span><?php endforeach;if(count($features)>3): ?><small>+<?= count($features)-3 ?></small><?php endif; ?></div></div></a><?php endforeach; ?></div>
<?php else: ?><section class="card table-scroll"><table><thead><tr><th>Sala</th><th>Tipo</th><th>Capacidade</th><th>Andar</th><th>Status</th><th><span class="sr-only">Ações</span></th></tr></thead><tbody><?php foreach($rows as $room): ?><tr><td><a class="table-room" href="<?= e(url('rooms',['action'=>'show','id'=>$room['id']])) ?>"><img src="public/assets/images/<?= e($room['image']) ?>" alt="" width="36" height="36"><strong><?= e($room['name']) ?></strong></a></td><td><span class="inline-meta"><?= icon(room_icon($room['type'])) ?><?= e($room['type']) ?></span></td><td><?= (int)$room['capacity'] ?></td><td><?= e($room['floor']) ?></td><td><?= badge($room['status']) ?></td><td><div class="actions"><a class="icon-button" href="<?= e(url('rooms',['action'=>'show','id'=>$room['id']])) ?>" aria-label="Ver <?= e($room['name']) ?>"><?= icon('eye') ?></a><a class="icon-button" href="<?= e(url('rooms',['action'=>'edit','id'=>$room['id']])) ?>" aria-label="Editar <?= e($room['name']) ?>"><?= icon('pencil') ?></a><?php delete_button('rooms',(int)$room['id'],$room['name']); ?></div></td></tr><?php endforeach; ?></tbody></table></section><?php endif;if(!$rows){empty_state();} ?>
